        const argCount = this.matchArgument(action, pattern.slice(valueStart).join(''));
        stop = valueStart + argCount;
        actionTuples.push([action, argv.slice(valueStart, stop)]);
        break;
      }
    }

    for (const [chosen, values] of actionTuples) {
      seen.add(chosen);
      this.takeAction(chosen, values, namespace);
    }
    return stop;
  }

  /** How many following tokens this action consumes, or a parse error. */
  matchArgument(action, patternText) {
    if (action.nargs === 0) {
      return 0;
    }
    if (patternText.startsWith('A')) {
      return 1;
    }
    throw new ArgumentError(action, 'expected one argument');
  }

  takeAction(action, values, namespace) {
    if (action.kind === HELP) {
      throw new ParserExit(0, { stdout: this.formatHelp() });
    }
    const [value] = values;
    namespace[action.dest] = action.type === null ? value : action.type(value);
  }

  hasNegativeNumberOptionals() {
    for (const optionString of this.optionStringActions.keys()) {
      if (NEGATIVE_NUMBER.test(optionString)) {
        return true;
      }
    }
    return false;
  }

  /**
   * Decide whether a token is an option. Returns `null` when it should be
   * treated as a value, otherwise `{action, optionString, explicitArg}` where a
   * `null` action means "looks like an option, but nothing matches".
   */
  parseOptional(argString) {
    if (argString === '') {
      return null;
    }
    if (!PREFIX_CHARS.includes(argString[0])) {
      return null;
    }
    const exact = this.optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) {
      // A lone '-' is a value.
      return null;
    }

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const action = this.optionStringActions.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArg: argString.slice(equals + 1) };
      }
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (tuples.length === 1) {
      return tuples[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals()) {
      return null;
    }
    if (argString.includes(' ')) {
      return null;
    }
    return { action: null, optionString: argString, explicitArg: null };
  }

  /** Every option string this abbreviation could stand for. */
  getOptionTuples(argString) {
    const tuples = [];

    if (PREFIX_CHARS.includes(argString[0]) && PREFIX_CHARS.includes(argString[1])) {
      // Long options must be separated from their value by '=' or a space.
      const equals = argString.indexOf('=');
      const optionPrefix = equals === -1 ? argString : argString.slice(0, equals);
      const explicitArg = equals === -1 ? null : argString.slice(equals + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          tuples.push({ action, optionString, explicitArg });
        }
      }
      return tuples;
    }

    // Single-character options may be concatenated with their value.
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        tuples.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(argString)) {
        tuples.push({ action, optionString, explicitArg: null });
      }
    }
    return tuples;
  }
}

export { ArgumentError, ParserExit };

