// Corpus generator for the "max-size" family.
// Emits /tmp/corpus/max-size.json : a JSON array of argv arrays.
import { mkdirSync, writeFileSync } from 'node:fs';
import { segwitEncode, bech32Encode, convertbits, CHARSET } from '/tmp/probe/gen.mjs';

const cases = [];
const seen = new Set();
function add(argv) {
  const key = JSON.stringify(argv);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
}
const ab = (a, b) => add(['--a', a, '--b', b]);

// Program bytes all < 32 so that convertbits(witprog,5,8) yields a real list
// (exercises the largest printable output), and a >=32 variant for the None path.
const lowProg = (n) => Array.from({ length: n }, (_, i) => i % 32);
const highProg = (n) => Array.from({ length: n }, (_, i) => 32 + (i % 200));

const rep = (ch, n) => ch.repeat(n);
// Deterministic "random-ish" charset filler with no '1' (CHARSET has no '1').
function fill(n, seed = 1) {
  let s = seed;
  let out = '';
  for (let i = 0; i < n; i += 1) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    out += CHARSET[(s >>> 7) % 32];
  }
  return out;
}

/* ------------------------------------------------------------------ *
 * 1. HRP length sweep with the maximum 40-byte witness program.
 *    total length = L + 1 + (1 + 64) + 6 = L + 72; L=83 -> 155 chars.
 * ------------------------------------------------------------------ */
for (let L = 1; L <= 92; L += 1) {
  const hrp = rep('a', L);
  const addr = segwitEncode(hrp, 1, lowProg(40));
  ab(hrp, addr);
}
for (const L of [95, 96, 100, 101, 127, 128, 155, 156, 200, 500, 1000, 4000, 20000]) {
  const hrp = rep('a', L);
  ab(hrp, segwitEncode(hrp, 1, lowProg(40)));
}

/* ------------------------------------------------------------------ *
 * 2. HRP sweep with the *smallest* legal payload (11 tail chars).
 *    hrp 83 + 11 = 95 total OK; hrp 84 + 11 = 96 total FAIL (spec bisection).
 * ------------------------------------------------------------------ */
for (let L = 76; L <= 92; L += 1) {
  const hrp = rep('a', L);
  ab(hrp, segwitEncode(hrp, 1, lowProg(2)));
}
// hrp 24 + 71 tail = 96 total -> OK per spec (proves there is no 90/96 limit).
for (const L of [17, 18, 19, 20, 23, 24, 25, 82, 83, 84]) {
  const hrp = rep('a', L);
  ab(hrp, segwitEncode(hrp, 1, lowProg(40)));
  ab(hrp, segwitEncode(hrp, 0, lowProg(32)));
  ab(hrp, segwitEncode(hrp, 0, lowProg(20)));
  ab(hrp, segwitEncode(hrp, 16, lowProg(40)));
  ab(hrp, segwitEncode(hrp, 16, highProg(40)));
}

/* ------------------------------------------------------------------ *
 * 3. Program-length boundaries (2 / 40 are the accept window) at max HRP.
 * ------------------------------------------------------------------ */
for (const hrpLen of [1, 82, 83, 84]) {
  const hrp = rep('a', hrpLen);
  for (const witver of [0, 1, 2, 15, 16, 17, 31]) {
    for (const plen of [0, 1, 2, 3, 19, 20, 21, 31, 32, 33, 39, 40, 41, 42, 64]) {
      const addr = segwitEncode(hrp, witver, lowProg(plen));
      if (addr !== null) ab(hrp, addr);
    }
  }
}

/* ------------------------------------------------------------------ *
 * 4. The exact 83/84 crossing at every total length that matters, plus the
 *    case-folding interaction at max size.
 * ------------------------------------------------------------------ */
for (const L of [82, 83, 84, 85]) {
  const hrp = rep('a', L);
  for (const plen of [2, 20, 32, 40]) {
    const addr = segwitEncode(hrp, 1, lowProg(plen));
    ab(hrp, addr);
    ab(hrp, addr.toUpperCase()); // lower hrp arg + upper addr -> still decodes
    ab(hrp.toUpperCase(), addr.toUpperCase()); // hrpgot is lowered -> fails
    ab(hrp.toUpperCase(), addr); // fails
    // mixed case at maximum size
    ab(hrp, addr.slice(0, addr.length - 1) + addr[addr.length - 1].toUpperCase());
    ab(hrp, addr[0].toUpperCase() + addr.slice(1));
  }
}

/* ------------------------------------------------------------------ *
 * 5. HRP made of the extreme printable code points (33 '!' and 126 '~')
 *    at and just past 83 characters, plus one just outside the range.
 * ------------------------------------------------------------------ */
for (const ch of ['!', '~', '"', '/', ':', '@', '[', '`', '{', '|']) {
  for (const L of [82, 83, 84]) {
    const hrp = rep(ch, L);
    ab(hrp, segwitEncode(hrp, 1, lowProg(40)));
  }
}
for (const L of [83, 84]) {
  // ord 32 (space) and ord 127 (DEL) inside a maximal HRP -> rejected
  const hrp = rep('a', L - 1) + ' ';
  ab(hrp, segwitEncode(hrp, 1, lowProg(40)));
  const hrp2 = rep('a', L - 1) + '';
  ab(hrp2, segwitEncode(hrp2, 1, lowProg(40)));
}

/* ------------------------------------------------------------------ *
 * 6. pos + 7 > len boundary at maximal HRP: tail of 5 and 6 characters.
 * ------------------------------------------------------------------ */
for (const L of [1, 82, 83, 84, 85]) {
  const hrp = rep('a', L);
  const only = bech32Encode(hrp, []); // tail is exactly the 6 checksum chars
  ab(hrp, only);
  ab(hrp, only.slice(0, -1)); // tail 5 -> pos+7 > len
  ab(hrp, `${only}q`); // tail 7, checksum now wrong
}

/* ------------------------------------------------------------------ *
 * 7. Raw (non-segwit) bech32 with very large 5-bit payloads and a *valid*
 *    checksum: bech32 layer succeeds, segwit layer rejects on length.
 * ------------------------------------------------------------------ */
for (const dataLen of [60, 64, 65, 66, 67, 70, 71, 72, 100, 200, 400, 1000, 1024, 4000, 16000]) {
  for (const hrpLen of [1, 83, 84]) {
    const hrp = rep('a', hrpLen);
    const data = Array.from({ length: dataLen }, (_, i) => i % 32);
    ab(hrp, bech32Encode(hrp, data));
  }
}
// exactly 40 / 41 decoded bytes from a raw payload (padding-sensitive)
for (const hrpLen of [83, 84]) {
  const hrp = rep('a', hrpLen);
  for (const n of [63, 64, 65, 66, 67]) {
    const data = [1, ...Array.from({ length: n }, () => 0)];
    ab(hrp, bech32Encode(hrp, data));
  }
}

/* ------------------------------------------------------------------ *
 * 8. Very long --b values (valid charset, invalid charset, separators in
 *    interesting places, case variants, out-of-range code points).
 * ------------------------------------------------------------------ */
const bigLens = [90, 91, 92, 96, 155, 156, 512, 1000, 1023, 1024, 1025, 2048, 4096, 8192, 65536, 99999];
for (const n of bigLens) {
  ab('a', fill(n));                            // valid charset, no '1' -> pos<0
  ab('a', rep('b', n));                        // 'b' not in CHARSET, no '1'
  ab('a', rep('1', n));                        // all separators
  ab('a', `a1${fill(n)}`);                     // pos=1, bad checksum
  ab('a', `${fill(n)}1qqqqqq`);                // pos huge (>83) -> reject
  ab('a', `${rep('a', 83)}1${fill(n)}`);       // pos=83 exactly, bad checksum
  ab(rep('a', 83), `${rep('a', 83)}1${fill(n)}`);
  ab('a', `${rep('a', 84)}1${fill(n)}`);       // pos=84 -> reject
  ab('a', `${fill(n)}1`);                      // trailing '1'
  ab('a', fill(n).toUpperCase());
  ab('a', `A1${fill(n)}`.slice(0, n));         // mixed case, long
  ab('a', `${fill(n - 1)} `);                  // ord 32 at the end
  ab('a', `${fill(n - 1)}ÿ`);             // non-ASCII at the end
  ab('a', `ÿ${fill(n - 1)}`);             // non-ASCII at the front
  ab('a', `${fill(n - 2)}\u{1f600}`);          // astral char
  ab('a', `${rep('b', n)}1qqqqqq`);            // invalid charset before '1'
  ab('a', `a1${rep('b', n)}`);                 // invalid charset after '1'
}

/* ------------------------------------------------------------------ *
 * 9. Very long --b with a *correct* checksum (so the bech32 layer really
 *    walks the whole payload) at maximal and just-past-maximal HRP.
 * ------------------------------------------------------------------ */
for (const dataLen of [500, 1000, 2000, 8000, 20000]) {
  for (const hrpLen of [1, 83, 84]) {
    const hrp = rep('a', hrpLen);
    const data = Array.from({ length: dataLen }, (_, i) => (i * 7) % 32);
    ab(hrp, bech32Encode(hrp, data));
  }
}

/* ------------------------------------------------------------------ *
 * 10. Very long --a values.
 * ------------------------------------------------------------------ */
for (const n of [83, 84, 85, 90, 100, 155, 1000, 4096, 65536, 99999]) {
  ab(rep('a', n), 'bc1pqypqj3p230');
  ab(rep('a', n), `${rep('a', n)}1${fill(11)}`);
  const hrp = rep('a', n);
  const addr = segwitEncode(hrp, 1, lowProg(40));
  ab(hrp, addr);
  ab('bc', addr);
  ab(rep('a', n), rep('a', n));
  ab(rep('a', n), '');
  ab('', rep('a', n));
  ab(rep('ÿ', n), 'bc1pqypqj3p230');
}
// both arguments maximal-length
for (const n of [65536, 99999]) {
  ab(rep('a', n), rep('b', n));
  ab(fill(n, 9), fill(n, 11));
}

/* ------------------------------------------------------------------ *
 * 11. Argparse surface with oversized tokens.
 * ------------------------------------------------------------------ */
const huge = rep('z', 99999);
add(['--a', huge, '--b', huge]);
add([`--a=${huge}`, '--b', 'bc1pqypqj3p230']);
add(['--a', 'bc', `--b=${huge}`]);
add(['--a', 'bc', '--b', `-${huge}`]);          // option-like -> expected one argument
add(['--a', 'bc', '--b', `- ${rep('z', 5000)}`]); // has a space -> value
add(['--a', 'bc', '--b', `-${rep('9', 5000)}`]);  // negative number -> value
add(['--a', 'bc', '--b', 'bc1pqypqj3p230', huge]); // unrecognized, huge
add(['--a', 'bc', huge, '--b', 'bc1pqypqj3p230']);
add(['--a', 'bc', '--b']);
add([`--${rep('a', 5000)}`, 'x']);
add(['--a', 'bc', '--b', 'bc1pqypqj3p230', '--a', huge]);
add(['--h', '--a', huge]);
add(['--a', huge]);
add(['--b', huge]);
add(['--', '--a', huge, '--b', huge]);
add(['--a', rep('a', 83), '--b', segwitEncode(rep('a', 83), 1, lowProg(40))]);
add(['--a', rep('a', 84), '--b', segwitEncode(rep('a', 84), 1, lowProg(40))]);

/* ------------------------------------------------------------------ *
 * 12. Spec regression anchors at the documented extremes.
 * ------------------------------------------------------------------ */
ab('bc', 'bc1pw508d6qejxtdg4y5r3zarvary0c5xw7kw508d6qejxtdg4y5r3zarvary0c5xw7k7grplx');
ab('bc', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4');
ab('tb', 'tb1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3q0sl5k7');
ab('bc', 'bc1sw50qa3jx3s');

// sanity: the documented 155-char maximum really is 155 characters
const maxHrp = rep('a', 83);
const maxAddr = segwitEncode(maxHrp, 1, lowProg(40));
if (maxAddr.length !== 155) throw new Error(`expected 155, got ${maxAddr.length}`);
const roundTrip = convertbits(lowProg(40), 8, 5);
if (roundTrip.length !== 64) throw new Error(`expected 64 data chars, got ${roundTrip.length}`);

mkdirSync('/tmp/corpus', { recursive: true });
writeFileSync('/tmp/corpus/max-size.json', JSON.stringify(cases));
const maxArg = Math.max(...cases.map((c) => Math.max(...c.map((t) => t.length))));
console.log(`cases=${cases.length} longestToken=${maxArg} maxAddrLen=${maxAddr.length}`);

